import { readFileSync } from 'node:fs';
import { describe, expect, test } from 'vitest';

import words from '../lib/petNameWords.json';

// desk/lib/pet-name.hoon carries the desk's copy of the word lists. It is
// generated by scripts/petNameHoon.ts; rerun that when this fails.
const hoon = readFileSync(
  new URL('../../../../desk/lib/pet-name.hoon', import.meta.url),
  'utf8'
);

function hoonList(arm: string): string[] {
  const body = hoon.split(`\n++  ${arm}\n`)[1]?.split('\n  ==')[0] ?? '';
  return [...body.matchAll(/'([a-z]+)'/g)].map((match) => match[1]);
}

describe('desk/lib/pet-name.hoon', () => {
  test.each([
    'galaxies',
    'adverbs',
    'adjectives',
    'colors',
    'animals',
    'comets',
  ] as const)('has the %s word list', (arm) => {
    expect(hoonList(arm)).toEqual(words[arm]);
  });

  test('names the word-list version it was made from', () => {
    expect(hoon).toContain(`(version ${words.version})`);
  });
});
